import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new file inside {@code dir} with a sanitized name.
     *
     * @param dir  the target directory where the file will be created
     * @param name the requested file name (may come from an untrusted source)
     * @return a {@link File} instance that does not conflict with existing files
     * @throws IllegalArgumentException if the name would cause a path‑traversal
     *                                  outside of {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory cannot be null");
        }
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("File name cannot be null or empty");
        }

        // Strip query parameters that may appear in URLs or ZIP entries
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the supplied name against the target directory and normalize
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path namePath = Paths.get(name).normalize();

        // Reject absolute paths or paths that escape the target directory
        Path resolvedPath = dirPath.resolve(namePath).normalize();
        if (!resolvedPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempted path traversal detected: " + name);
        }

        // Build the initial File object
        File file = resolvedPath.toFile();

        // If a file with the same name already exists, append a numeric suffix
        String dot = namePath.toString().indexOf('.') >= 0
                     ? namePath.toString()
                     : "";
        int dotIndex = name.indexOf('.');
        String prefix = dotIndex < 0 ? name : name.substring(0, dotIndex);
        String suffix = dotIndex < 0 ? "" : name.substring(dotIndex);

        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Ensure the parent directory exists
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
