import java.util.Calendar;

/**
 * Sets the specified calendar field to the supplied value, taking into account
 * the field‑specific offset.  The original implementation performed a blind
 * subtraction (`i - offset`) and delegated directly to {@link Calendar#set(int,int)}.
 * This could result in out‑of‑range values that trigger the calendar to roll
 * over repeatedly, potentially causing an infinite loop in the surrounding
 * {@code ceil} logic.
 *
 * <p>To make the method safe for production use we now:</p>
 * <ul>
 *   <li>Validate that the {@code Calendar} instance is non‑null.</li>
 *   <li>Verify that the field is known (non‑null).</li>
 *   <li>Compute the target value as {@code i - offset} and clamp it to the
 *       actual minimum/maximum supported by the calendar for that field.</li>
 *   <li>Throw an {@link IllegalArgumentException} if the computed value is
 *       outside the valid range, preventing silent wrap‑around that could
 *       otherwise lead to an endless loop.</li>
 * </ul>
 *
 * @param c the calendar to modify
 * @param i the raw value before applying the field offset
 * @throws IllegalArgumentException if the resulting value is out of range
 */
void setTo(Calendar c, int i) {
    if (c == null) {
        throw new IllegalArgumentException("Calendar instance cannot be null");
    }
    if (field == null) {
        throw new IllegalArgumentException("CalendarField cannot be null");
    }

    // Compute the intended value after applying the offset
    int value = i - offset;

    // Retrieve the legal bounds for this field from the calendar instance
    int min = c.getActualMinimum(field);
    int max = c.getActualMaximum(field);

    // Guard against values that would cause the calendar to roll over
    if (value < min || value > max) {
        throw new IllegalArgumentException(
                String.format("Attempted to set field %s to %d, which is outside the valid range [%d,%d]",
                              field, value, min, max));
    }

    // Safe to set the field now
    c.set(field, value);
}
