    /**
     * Creates a {@link Transformer} from the supplied XSLT template stream.
     *
     * <p>This method enforces strict XSLT processing rules to prevent
     * remote code execution via malicious templates. It configures the
     * {@link TransformerFactory} with {@code FEATURE_SECURE_PROCESSING},
     * disables external DTD and stylesheet access, and validates the
     * template before returning the transformer.</p>
     *
     * @param templateStream the XSLT template input stream
     * @return a securely configured {@link Transformer}
     * @throws IOException if the stream cannot be read or closed
     */
    private static Transformer createTransformer(InputStream templateStream) throws IOException {
        Objects.requireNonNull(templateStream, "templateStream must not be null");

        // Create a fresh factory for each call to avoid shared mutable state
        TransformerFactory factory = TransformerFactory.newInstance();

        try {
            // Enable secure processing to limit resource usage and disable
            // potentially dangerous extensions.
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Explicitly deny external DTD and stylesheet access to prevent
            // XXE and external resource loading.
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");

