import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely expands archive entries into {@code targetDirectory}.  The method
     * performs rigorous path validation to prevent directory‑traversal attacks.
     *
     * @param supplier      provides the next readable entry
     * @param writer        writes entry data to an {@link OutputStream}
     * @param targetDirectory the root directory where entries are extracted
     * @throws IOException if extraction fails or a path validation error occurs
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once
        Path targetDirPath = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Reject empty or null entry names
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("Archive entry has an empty name");
            }

            // Reject absolute paths or paths that could escape the target directory
            if (entryName.startsWith("/") || entryName.startsWith("\\") ||
                entryName.matches("^[a-zA-Z]:.*")) {
                throw new IOException("Archive entry contains an absolute path: " + entryName);
            }

            // Normalize the entry name to use '/' as separator
            entryName = entryName.replace('\\', '/');

            // Resolve and normalize the full path
            Path entryPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resulting path is still within the target directory
            if (!entryPath.startsWith(targetDirPath)) {
                throw new IOException("Expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            File f = entryPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("Failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist
                Path parentPath = entryPath.getParent();
                if (parentPath != null) {
                    Files.createDirectories(parentPath);
                }

                // Write the file contents
                try (OutputStream o = Files.newOutputStream(entryPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, o);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
