private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Handle entries that use a data descriptor – they are cached in lastStoredEntry
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // cache the entry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Size must be non‑negative for a STORED entry; otherwise the archive is malformed.
    if (csize < 0) {
        throw new IOException("Invalid entry size: " + csize);
    }

    // If we have already read the declared amount of data, signal EOF.
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Ensure we do not attempt to read more than the remaining declared size.
    long remaining = csize - current.bytesRead;
    if (remaining <= 0) {
        return -1;
    }

    // Refill the internal buffer if it is exhausted.
    if (buf.position() >= buf.limit()) {
        buf.position(0);
        int l = in.read(buf.array());
        if (l == -1) {
            // Unexpected end of stream – the entry is truncated.
            throw new IOException("Unexpected end of entry data for " + current.entry.getName());
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Determine how many bytes to copy into the caller's buffer.
    int toRead = Math.min(buf.remaining(), length);
    if (remaining < toRead) {
        toRead = (int) remaining; // safe cast – remaining <= Integer.MAX_VALUE
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;

    // If we have reached the declared size, signal EOF on subsequent reads.
    return toRead;
}
