import java.io.InputStream;
import java.io.StringReader;
import java.io.IOException;
import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.apache.camel.Exchange;
import org.apache.camel.Expression;
import org.apache.camel.NoTypeConversionAvailableException;
import org.apache.camel.Predicate;
import org.apache.camel.WrappedFile;
import org.apache.camel.component.bean.BeanInvocation;
import org.apache.camel.spi.NamespaceAware;
import org.apache.camel.support.ServiceSupport;

public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // other methods

    /**
     * Securely converts the body into a {@link Document} or an {@link InputSource}.
     * <p>
     * The method now parses XML strings and streams using a {@link DocumentBuilderFactory}
     * that has external entity resolution disabled and secure processing enabled,
     * mitigating XXE attacks.
     */
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Object answer = null;
        Class<?> type = getDocumentType();
        Exception cause = null;

        // If a specific document type is requested, try to convert it first
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e;
            }
        }

        // If conversion failed or no type was specified, handle common body types
        if (answer == null) {
            if (body instanceof WrappedFile) {
                InputStream is = exchange.getContext()
                                         .getTypeConverter()
                                         .convertTo(InputStream.class, exchange, body);
                try {
                    answer = parseSecure(new InputSource(is));
                } finally {
                    try { is.close(); } catch (IOException ignore) {}
                }
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext()
                                            .getTypeConverter()
                                            .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                answer = parseSecure(new InputSource(new StringReader((String) body)));
            } else if (body instanceof InputSource) {
                // If the caller explicitly passed an InputSource, parse it securely
                answer = parseSecure((InputSource) body);
            }
        }

        // Fallback handling
        if (type == null && answer == null) {
            answer = body;
        } else if (answer == null) {
            if (cause != null) {
                throw cause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
            }
        }

        return answer;
    }

    /**
     * Parses the given {@link InputSource} into a {@link Document} using a
     * {@link DocumentBuilderFactory} that is configured to prevent XXE.
     *
     * @param source the input source containing XML
     * @return a parsed {@link Document}
     * @throws Exception if parsing fails
     */
    private Document parseSecure(InputSource source) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // Enable secure processing
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // Disable external DTDs and schemas
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
        dbf.setNamespaceAware(true);

        DocumentBuilder builder = dbf.newDocumentBuilder();
        return builder.parse(source);
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods

}
