import com.google.refine.importers.tree.TreeImportingParserBase;

public class XmlImporter extends TreeImportingParserBase {

    // other methods

    /**
     * Creates a secure {@link XMLStreamReader} that protects against XXE attacks.
     *
     * <p>
     * The factory is configured to:
     * <ul>
     *   <li>Disable DTD support ({@code SUPPORT_DTD = false})</li>
     *   <li>Prevent resolution of external entities ({@code IS_SUPPORTING_EXTERNAL_ENTITIES = false})</li>
     *   <li>Enable namespace awareness for proper XML parsing</li>
     *   <li>Coalesce adjacent character data and replace entity references as before</li>
     * </ul>
     * </p>
     *
     * @param inputStream the raw XML input stream
     * @return a protected {@link XMLStreamReader}
     * @throws XMLStreamException if the XML cannot be parsed
     * @throws IOException if an I/O error occurs
     */
    final static private XMLStreamReader createXMLStreamReader(InputStream inputStream)
            throws XMLStreamException, IOException {
        XMLInputFactory factory = XMLInputFactory.newInstance();

        // Preserve original behaviour
        factory.setProperty(XMLInputFactory.IS_COALESCING, true);
        factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, true);

        // Security hardening – mitigate XXE
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, Boolean.FALSE);
        factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, Boolean.FALSE);
        factory.setProperty(XMLInputFactory.IS_NAMESPACE_AWARE, Boolean.TRUE);

        return factory.createXMLStreamReader(wrapPrefixRemovingInputStream(inputStream));
    }

    // other methods

}
